      set("[data-ea-highx]", usd(cur, r.high));
      set("[data-ea-month]", usd(cur, r.month));
      set("[data-ea-first]", usd(cur, roundFig(r.first)));
      set("[data-ea-low]", usd(cur, r.low));
      set("[data-ea-high]", usd(cur, r.high));
      set("[data-ea-reach]", short(A.reach));
      set("[data-ea-visits]", short(r.visits));
      set("[data-ea-eligible]", short(r.eligible));
      set("[data-ea-signups]", String(Math.round(r.signups)));
